 function animate(time){if(stopped)return;requestAnimationFrame(animate);const t=time*.001;waterUniforms.uTime.value=t;controls.update();for(const d of KINGDOMS){v.set(d.pos[0],.4,d.pos[2]+(d.id==='moon'?2.1:4.3)).project(camera);const label=labels[d.id];label.style.transform=`translate(-50%,-50%) translate(${(v.x*.5+.5)*host.clientWidth}px,${(-v.y*.5+.5)*host.clientHeight}px)`;label.style.visibility=v.z>1?'hidden':'visible';}if(motion){const t0=Math.min(1,(time-motion.start)/1800),e=t0*t0*(3-2*t0);boat.position.lerpVectors(motion.from,motion.to,e);if(t0===1)motion=null;}boat.position.y=Math.sin(t*1.8)*.045;boat.rotation.z=Math.sin(t*1.4)*.035;for(let i=0;i<birds.length;i++){const b=birds[i],a=t*.08+i*.8;b.position.set(Math.cos(a)*(8+i),5+i*.3,Math.sin(a)*(8+i)+2);b.rotation.y=-a;b.scale.y=.7+Math.sin(t*4+i)*.4;}for(const f of flags)f.rotation.y=Math.sin(t*2)*.15;renderer.render(scene,camera);}requestAnimationFrame(animate);
 return {update(s,instant=false){for(const d of KINGDOMS){const k=s.kingdoms[d.id];rings[d.id].visible=s.selected===d.id;labels[d.id].classList.toggle('selected',s.selected===d.id);labels[d.id].classList.toggle('allied',k.allied);labels[d.id].querySelector('small').textContent=k.allied?'盟友':s.location===d.id?'已停泊':k.trade?'通商':k.relation>=55?'友好':'中立';}if(s.location!==location||instant){const d=KINGDOMS.find(x=>x.id===s.location),to=d?new THREE.Vector3(d.pos[0]+.5,0,d.pos[2]+3.8):new THREE.Vector3(1.2,0,6);if(instant)boat.position.copy(to);else{motion={from:boat.position.clone(),to,start:performance.now()};boat.rotation.y=Math.atan2(to.x-boat.position.x,to.z-boat.position.z);}location=s.location;}},reset(){camera.position.set(29,38,43);controls.target.set(0,0,6);},zoom(factor){camera.position.sub(controls.target).multiplyScalar(factor).add(controls.target);},routes(value){routes.visible=value;},dispose(){stopped=true;renderer.dispose();controls.dispose();}};
